import{_ as o,r as n,o as l,c,e as t,a as p,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Чертежи - October CMS - 3.x","titleTemplate":false,"description":"Шаблонная структура для контента вашего сайта.","frontmatter":{"subtitle":"Шаблонная структура для контента вашего сайта."},"headers":[{"level":2,"title":"Entry","slug":"entry","link":"#entry","children":[{"level":3,"title":"Варианты Entry","slug":"варианты-entry","link":"#варианты-entry","children":[{"level":4,"title":"Единичные записи","slug":"единичные-записи","link":"#единичные-записи","children":[]},{"level":4,"title":"Структурные записи","slug":"структурные-записи","link":"#структурные-записи","children":[]},{"level":4,"title":"Потоковые записи","slug":"потоковые-записи","link":"#потоковые-записи","children":[]}]},{"level":3,"title":"Группы контента","slug":"группы-контента","link":"#группы-контента","children":[]},{"level":3,"title":"Пользовательские сообщения","slug":"пользовательские-сообщения","link":"#пользовательские-сообщения","children":[]},{"level":3,"title":"Отключение обязательных полей","slug":"отключение-обязательных-полеи","link":"#отключение-обязательных-полеи","children":[]},{"level":3,"title":"Конфигурация поиска страниц","slug":"конфигурация-поиска-страниц","link":"#конфигурация-поиска-страниц","children":[]}]},{"level":2,"title":"Global","slug":"global","link":"#global","children":[]},{"level":2,"title":"Mixin","slug":"mixin","link":"#mixin","children":[{"level":3,"title":"Использование миксина","slug":"использование-миксина","link":"#использование-миксина","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/tailor/blueprints.md","filePath":"3.x/ru/cms/tailor/blueprints.md"}'),d={name:"3.x/ru/cms/tailor/blueprints.md"};function u(i,a,k,g,y,m){const e=n("pre-heading"),s=n("post-heading");return l(),c("div",null,[t(e),a[0]||(a[0]=p("h1",null,"Чертежи",-1)),t(s),a[1]||(a[1]=r(`<h2 id="entry"><a href="#entry" class="header-anchor">#</a> Entry</h2><p>Чертёж Entry — это стандартная структура контента, используемая для определения разделов вашего сайта. Структуры контента и записи могут быть организованы различными способами, которые подробнее описаны ниже.</p><p>Тип <code>entry</code> поддерживает множественные записи и должен использоваться, когда не подходит ни один другой вариант.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Team\\Member
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Team Member

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> First Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>Чертёж Entry поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>Осмысленный и уникальный код для идентификации записи.</td></tr><tr><td><strong>type</strong></td><td>Тип чертежа, может быть вариантом <code>entry</code>, <code>single</code>, <code>structure</code> или <code>stream</code>.</td></tr><tr><td><strong>name</strong></td><td>Метка, отображаемая при работе с этой записью.</td></tr><tr><td><strong>fields</strong></td><td>поля формы, принадлежащие группе, см. <a href="./../../element/form-fields.html">поля формы</a>.</td></tr><tr><td><strong>groups</strong></td><td>ссылается на группу полей формы, переводя запись в режим групп (см. ниже).</td></tr><tr><td><strong>structure</strong></td><td>конфигурация структуры, используемая при типе <code>structure</code>.</td></tr><tr><td><strong>drafts</strong></td><td>включает черновики для этой записи. По умолчанию: <code>false</code></td></tr><tr><td><strong>softDeletes</strong></td><td>включает мягкое удаление для этой записи. По умолчанию: <code>true</code></td></tr><tr><td><strong>multisite</strong></td><td>включает мультисайт для этой записи, синхронизация записей между группой, локалью или всеми сайтами. Поддерживаемые значения: <code>true</code>, <code>false</code>, <code>sync</code>, <code>locale</code>, <code>all</code>. По умолчанию: <code>false</code></td></tr><tr><td><strong>pagefinder</strong></td><td>включает тип чертежа в <a href="./../../element/form/widget-pagefinder.html">виджет поиска страниц</a>, поддерживаемые значения: <code>true</code>, <code>false</code>, <code>item</code>, <code>list</code> или массив (см. ниже). По умолчанию: <code>true</code></td></tr><tr><td><strong>defaultSort</strong></td><td>используется типами <code>entry</code> и <code>stream</code>, устанавливает столбец и направление сортировки по умолчанию, когда пользовательские настройки не определены. Поддерживает строку или массив с ключами <code>column</code> и <code>direction</code>. Направление может быть <code>asc</code> для восходящего (по умолчанию) или <code>desc</code> для нисходящего порядка.</td></tr><tr><td><strong>customMessages</strong></td><td>настройка сообщений, используемых в пользовательском интерфейсе (см. ниже).</td></tr><tr><td><strong>showExport</strong></td><td>отображает кнопку на панели инструментов для экспорта записей. По умолчанию: <code>true</code>.</td></tr><tr><td><strong>showImport</strong></td><td>отображает кнопку на панели инструментов для импорта записей. По умолчанию: <code>true</code>.</td></tr></tbody></table></div><h3 id="варианты-entry"><a href="#варианты-entry" class="header-anchor">#</a> Варианты Entry</h3><p>Тип entry не имеет специфического поведения, но существует несколько вариантов для организации контента. Следующие типы являются вариантами entry.</p><ul><li><strong>entry</strong> — базовая запись для общих целей.</li><li><strong>single</strong> — единичная запись с выделенными полями, например: Страница «Контакты».</li><li><strong>structure</strong> — определённая структура записей, например: Документация.</li><li><strong>stream</strong> — поток записей с временными метками, например: Публикации блога.</li></ul><h4 id="единичные-записи"><a href="#единичные-записи" class="header-anchor">#</a> Единичные записи</h4><p>Тип <code>single</code> создаёт одну запись для каждого определения секции. Это полезно для одноразового контента, такого как Главная страница или страница «Контакты». Следующий пример определяет секцию <strong>Homepage</strong> с текстовым полем Welcome Message (<code>welcome_message</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Homepage
<span class="token key atrule">type</span><span class="token punctuation">:</span> single
<span class="token key atrule">name</span><span class="token punctuation">:</span> Homepage Content

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">welcome_message</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Welcome Message
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><h4 id="структурные-записи"><a href="#структурные-записи" class="header-anchor">#</a> Структурные записи</h4><p>Тип <code>structure</code> допускает множественные структурированные записи с родительско-дочерними отношениями. Это полезно для вложенного контента, такого как раздел Документации. Записи типа <code>structure</code> могут быть отсортированы. Порядок сортировки можно изменить перетаскиванием в режиме списка. Следующий пример определяет древовидную секцию <strong>Documentation</strong> с полем Article Content (<code>article_content</code>) типа markdown.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Docs\\Article
<span class="token key atrule">type</span><span class="token punctuation">:</span> structure
<span class="token key atrule">name</span><span class="token punctuation">:</span> Documentation Article

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Article Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> markdown
</code></pre></div><p>По умолчанию структуры поддерживают неограниченную вложенность, однако вы можете указать максимальную глубину дерева с помощью <code>maxDepth</code> в свойстве <code>structure</code>. В следующем примере допускается только верхний уровень и второй уровень.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">type</span><span class="token punctuation">:</span> structure

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
    <span class="token comment"># ...</span>
</code></pre></div><p>Свойство <code>structure</code> поддерживает следующие значения.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>maxDepth</strong></td><td>Максимальная глубина структуры. По умолчанию: <code>0</code> для неограниченной.</td></tr><tr><td><strong>treeExpanded</strong></td><td>должны ли узлы дерева быть развёрнуты по умолчанию. По умолчанию: <code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>отображает интерфейс для изменения порядка записей. По умолчанию: <code>true</code></td></tr><tr><td><strong>showSorting</strong></td><td>разрешает сортировку записей, отключает структуру при сортировке. По умолчанию: <code>true</code></td></tr></tbody></table></div><h4 id="потоковые-записи"><a href="#потоковые-записи" class="header-anchor">#</a> Потоковые записи</h4><p>Тип <code>stream</code> используется для записей на основе времени, которые часто перечисляются в хронологическом порядке. Это полезно для публикации недавней активности, например раздела Блога. Следующий пример определяет секцию ленты <strong>Blog</strong> с полем Post Content (<code>content</code>) типа rich editor.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Post Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
</code></pre></div><p>Свойство <code>defaultSort</code> используется для установки столбца сортировки по умолчанию при отображении записей чертежа в виде списка. По умолчанию устанавливается дата публикации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">defaultSort</span><span class="token punctuation">:</span>
    <span class="token key atrule">column</span><span class="token punctuation">:</span> title
    <span class="token key atrule">direction</span><span class="token punctuation">:</span> asc
</code></pre></div><h3 id="группы-контента"><a href="#группы-контента" class="header-anchor">#</a> Группы контента</h3><p>Все записи опционально поддерживают возможность определения нескольких групп контента для секции. Например, секция блога может иметь обычную публикацию и избранную публикацию — это две группы записей.</p><p>Группы записей определяются свойством <strong>groups</strong> в файле чертежа секции, и для каждого типа могут быть указаны различные <strong>fields</strong>. Выбранное значение группы доступно как атрибут <code>content_group</code> на записи.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">groups</span><span class="token punctuation">:</span>
    <span class="token key atrule">regular_post</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Regular Post
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token comment"># ...</span>

    <span class="token key atrule">featured_post</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Featured Post
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token comment"># ...</span>
</code></pre></div><div class="custom-block tip"><p>Рекомендуется использовать <a href="#mixin">чертежи миксинов</a> для группировки общих определений полей.</p></div><h3 id="пользовательские-сообщения"><a href="#пользовательские-сообщения" class="header-anchor">#</a> Пользовательские сообщения</h3><p>Укажите свойство <code>customMessages</code> для переопределения стандартных сообщений интерфейса. Значения могут быть обычным текстом или ссылкой на <a href="./../../extend/system/localization.html">строку локализации</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> Create New Event
</code></pre></div><p>Следующие сообщения доступны для переопределения.</p><details class="custom-block details"><summary>Просмотреть список доступных сообщений</summary><div class="table"><table tabindex="0"><thead><tr><th>Сообщение</th><th>Сообщение по умолчанию</th></tr></thead><tbody><tr><td><strong>buttonCreate</strong></td><td>Create :name Entry</td></tr><tr><td><strong>titleIndexList</strong></td><td>Manage :name Entries</td></tr><tr><td><strong>titleCreateForm</strong></td><td>Create :name</td></tr><tr><td><strong>titleUpdateForm</strong></td><td>Update :name</td></tr><tr><td><strong>pagefinderItemType</strong></td><td>:name Entry</td></tr><tr><td><strong>pagefinderListType</strong></td><td>All :name Entries</td></tr></tbody></table></div></details><h3 id="отключение-обязательных-полеи"><a href="#отключение-обязательных-полеи" class="header-anchor">#</a> Отключение обязательных полей</h3><p>Запись требует заполнения полей <code>title</code> и <code>slug</code> перед сохранением, кроме того, поле <code>slug</code> должно быть уникальным. Вы можете изменить эту функциональность, переопределив эти поля в вашем чертеже — установив свойство <code>validation</code> в <strong>false</strong> или установив свойство <code>hidden</code> в <strong>true</strong> для скрытия из пользовательского интерфейса. Следующий пример отключает валидацию для обоих полей и скрывает поле slug.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>

    <span class="token key atrule">slug</span><span class="token punctuation">:</span>
        <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h3 id="конфигурация-поиска-страниц"><a href="#конфигурация-поиска-страниц" class="header-anchor">#</a> Конфигурация поиска страниц</h3><p>По умолчанию все записи включены в значения поиска <a href="./../../element/form/widget-pagefinder.html">виджета поиска страниц</a>. Это можно отключить, установив <strong>pagefinder</strong> в <code>false</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Вы можете ограничить контекст поиска страниц, разрешив поиск страницы только как единичный <code>item</code> (например, Публикация блога) или как <code>list</code> элементов (например, Все публикации блога), или при значении <code>all</code> будут отображаться оба варианта.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> item
<span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> list
</code></pre></div><p>Поиск страниц автоматически разрешает атрибуты <code>id</code>, <code>code</code>, <code>slug</code> и <code>fullslug</code> и использует их в качестве замен в <a href="./../themes/pages.html">параметрах URL страницы</a>. Вы можете указать пользовательские <strong>replacements</strong> в виде массива, используя свойства <strong>pagefinder</strong>, включая необязательный <strong>context</strong> выше.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span>
    <span class="token key atrule">context</span><span class="token punctuation">:</span> list
    <span class="token key atrule">replacements</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
</code></pre></div><p>Каждый ключ замены должен соответствовать имени URL-параметра и использовать точечную нотацию для пути к значению атрибута. Рассмотрим следующий пример URL для страницы публикации блога.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:author/:category/:slug/:id</span>&quot;</span>
</code></pre></div><p>Следующие <strong>replacements</strong> установят параметр <code>:author</code> в значение атрибута slug связанного автора, а параметр <code>:category</code> в значение атрибута slug первой связанной категории.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span>
    <span class="token key atrule">replacements</span><span class="token punctuation">:</span>
        <span class="token key atrule">author</span><span class="token punctuation">:</span> author.slug
        <span class="token key atrule">category</span><span class="token punctuation">:</span> categories.0.slug
</code></pre></div><h2 id="global"><a href="#global" class="header-anchor">#</a> Global</h2><p>Глобальные записи используются для определения глобально доступного контента для вашего сайта. Значения полей часто используются в <a href="./../../cms/themes/layouts.html">CMS-макетах</a> и содержат настройки, такие как ссылки на социальные сети.</p><p>Следующий пример определяет глобальную запись <strong>Footer Config</strong> с текстовым полем Facebook Link (<code>facebook_link</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Site\\Footer
<span class="token key atrule">type</span><span class="token punctuation">:</span> global
<span class="token key atrule">name</span><span class="token punctuation">:</span> Footer Config

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">facebook_link</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Facebook Link
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>Чертёж Global поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>Осмысленный и уникальный код для идентификации записи.</td></tr><tr><td><strong>name</strong></td><td>Метка, отображаемая при работе с этой записью.</td></tr><tr><td><strong>fields</strong></td><td>поля формы, принадлежащие группе, см. <a href="./../../element/form-fields.html">поля формы</a>.</td></tr><tr><td><strong>multisite</strong></td><td>включает мультисайт для этой записи, поддерживаемые значения: <code>true</code>, <code>false</code>. По умолчанию: <code>false</code></td></tr><tr><td><strong>formSize</strong></td><td>размер формы настроек, поддерживаемые значения: <code>tiny</code>, <code>small</code>, <code>medium</code>, <code>large</code>, <code>huge</code>, <code>giant</code>, <code>adaptive</code>. По умолчанию: <code>huge</code>.</td></tr></tbody></table></div><h2 id="mixin"><a href="#mixin" class="header-anchor">#</a> Mixin</h2><p>Миксины — это группы полей, используемые для избежания повторений при определении структур контента. Например, поле Location может использоваться в нескольких местах, но мы можем определить его один раз с помощью определения миксина.</p><p>Следующий пример определяет коллекцию <strong>Location</strong> с текстовыми полями Country (<code>country_code</code>) и State (<code>state_code</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Fields\\Location
<span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
<span class="token key atrule">name</span><span class="token punctuation">:</span> Location

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">country_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text

    <span class="token key atrule">state_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> State
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>Чертёж Mixin поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>Осмысленный и уникальный код для идентификации записи.</td></tr><tr><td><strong>name</strong></td><td>Метка, отображаемая при работе с этой записью.</td></tr><tr><td><strong>fields</strong></td><td>поля формы, принадлежащие группе, см. <a href="./../../element/form-fields.html">поля формы</a>.</td></tr></tbody></table></div><div class="custom-block tip"><p>Рекомендуется добавлять к файлу миксина и именам полей префикс в виде подчёркивания (_), чтобы тип чертежа было легко найти. Например: <code>_location_fields.yaml</code></p></div><h3 id="использование-миксина"><a href="#использование-миксина" class="header-anchor">#</a> Использование миксина</h3><p>Чтобы включить эти поля в ваши записи, как и любое другое поле формы, используйте <code>type</code> равный <strong>mixin</strong> и укажите UUID или handle в свойстве <code>source</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">_location_fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Fields\\Location
</code></pre></div><p>Подробнее см. <a href="./../../element/content/field-mixin.html">поле миксина</a>.</p><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../element/content/field-mixin.html">Поле контента Mixin</a></li></ul></div>`,67))])}const v=o(d,[["render",u]]);export{f as __pageData,v as default};
